//lxrtxdy!
#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
const int MAX_NODES = 7100;
const i64 INF_FLOW = 1000000000LL;

struct Dinic {
    struct Edge {
        int src, dst;
        i64 flow, cap;
    };

    int src_node, dst_node;
    vector<Edge> edge_list;
    vector<int> adj[MAX_NODES];
    int level[MAX_NODES], iter[MAX_NODES];

    void reset() {
        edge_list.clear();
        for (int i = 0; i < MAX_NODES; ++i) adj[i].clear();
    }

    void connect(int u, int v, i64 capacity) {
        edge_list.push_back({u, v, 0, capacity});
        edge_list.push_back({v, u, 0, 0});
        adj[u].push_back(edge_list.size() - 2);
        adj[v].push_back(edge_list.size() - 1);
    }

    bool build_levels() {
        fill(level, level + MAX_NODES, -1);
        queue<int> q;
        level[src_node] = 0;
        q.push(src_node);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int eid : adj[u]) {
                auto &e = edge_list[eid];
                if (e.cap > e.flow && level[e.dst] < 0) {
                    level[e.dst] = level[u] + 1;
                    q.push(e.dst);
                }
            }
        }
        return level[dst_node] >= 0;
    }

    i64 push_flow(int u, i64 flow) {
        if (u == dst_node || !flow) return flow;
        for (int &i = iter[u]; i < (int)adj[u].size(); ++i) {
            int eid = adj[u][i];
            auto &e = edge_list[eid];
            if (level[e.dst] == level[u] + 1 && e.cap > e.flow) {
                i64 pushed = push_flow(e.dst, min(flow, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edge_list[eid ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    i64 compute() {
        i64 total = 0;
        while (build_levels()) {
            fill(iter, iter + MAX_NODES, 0);
            i64 pushed;
            while ((pushed = push_flow(src_node, INF_FLOW)) > 0)
                total += pushed;
        }
        return total;
    }
};

Dinic solver;
char map1[14][14], map2[14][14];
bool marked[14][14];
int time_dist[14][14];
int N, T;
int sink_map[103];

void compute_distances(int x, int y) {
    for (int i = 0; i < 14; ++i) fill(time_dist[i], time_dist[i] + 14, 111);
    queue<tuple<int, int, int>> q;
    time_dist[x][y] = 0;
    q.emplace(x, y, 0);

    const int dr[4] = {1, 0, 0, -1};
    const int dc[4] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [r, c, d] = q.front(); q.pop();
        if (marked[r][c]) continue;
        marked[r][c] = true;
        time_dist[r][c] = d;

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 1 && nr <= N && nc >= 1 && nc <= N &&
                !marked[nr][nc] && map1[nr][nc] != 'Y') {
                q.emplace(nr, nc, d + 1);
            }
        }
    }
}

int encode(int level, int r, int c) {
    return level * N * N + (r - 1) * N + c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    for (int i = 1; i <= N; ++i) cin >> (map1[i] + 1);
    for (int i = 1; i <= N; ++i) cin >> (map2[i] + 1);

    solver.reset();
    solver.src_node = 0;
    solver.dst_node = MAX_NODES - 2;

    int start_r = 0, start_c = 0;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (map1[i][j] == 'Z') {
                start_r = i; start_c = j;
                break;
            }
        }
    }

    for (int i = 1; i <= N * N; ++i)
        sink_map[i] = MAX_NODES - 3 - (N * N - i);

    compute_distances(start_r, start_c);

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (isdigit(map1[i][j]))
                solver.connect(solver.src_node, encode(0, i, j), map1[i][j] - '0');
            if (isdigit(map2[i][j]))
                solver.connect(sink_map[encode(0, i, j)], solver.dst_node, map2[i][j] - '0');
            solver.connect(encode(0, i, j), sink_map[encode(0, i, j)], INF_FLOW);
        }
    }

    const int dr[4] = {1, 0, 0, -1};
    const int dc[4] = {0, 1, -1, 0};

    for (int step = 1; step <= T; ++step) {
        for (int r = 1; r <= N; ++r) {
            for (int c = 1; c <= N; ++c) {
                if (map1[r][c] == 'Y' || map1[r][c] == 'Z') continue;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr >= 1 && nr <= N && nc >= 1 && nc <= N &&
                        map1[nr][nc] != 'Y' && map1[nr][nc] != 'Z' &&
                        time_dist[r][c] >= step && time_dist[nr][nc] >= step) {
                        solver.connect(encode(step - 1, nr, nc), encode(step, r, c), INF_FLOW);
                    }
                }
                solver.connect(encode(step, r, c), sink_map[encode(0, r, c)], INF_FLOW);
            }
        }
    }

    cout << solver.compute() << '\n';
    return 0;
}
